<template><section class="community-moderation"><button @click="load(false)">신고 새로고침</button><p v-if="error" role="alert">{{error}}</p><p v-if="!rows.length">접수된 커뮤니티 신고가 없습니다.</p><article v-for="r in rows" :key="r.reportId"><header><strong>신고 #{{r.reportId}} · {{r.post.author}}</strong><span>{{r.post.hidden?'숨김':'공개'}}</span></header><h3>{{r.post.title||'댓글'}}</h3><p>{{r.post.body}}</p><img v-if="r.post.imageUrl" v-private-src.admin="r.post.imageUrl" alt="신고 게시글 사진" tabindex="0" role="button" aria-label="신고 사진 확대" style="max-width:240px;max-height:240px;object-fit:contain;border-radius:12px"/><blockquote>신고 사유: {{r.reason}}</blockquote><button :disabled="busy" @click="moderate(r)">{{r.post.hidden?'공개로 되돌리기':'게시물 숨기기'}}</button></article><button v-if="more" @click="load(true)">더 보기</button></section></template><script setup>import {ref,onMounted} from 'vue';import api from '../../api/api';const rows=ref([]),error=ref(''),more=ref(false),busy=ref(false);async function load(append=false){try{const {data}=await api.get('/admin/community/reports',{params:{before:append?rows.value.at(-1)?.reportId:0}});rows.value=append?[...rows.value,...data]:data;more.value=data.length===30;error.value='';}catch(e){error.value=e.response?.data?.message||'신고를 불러오지 못했습니다.';}}async function moderate(r){busy.value=true;try{await api.put(`/admin/community/${r.postId}`,{hidden:!r.post.hidden});await load();}catch(e){error.value=e.response?.data?.message||'변경하지 못했습니다.';}finally{busy.value=false;}}onMounted(()=>load());</script><style scoped>.community-moderation article{background:white;border:1px solid #e9ddd5;border-radius:15px;margin:16px 0;padding:20px}.community-moderation header{display:flex;justify-content:space-between}.community-moderation p{white-space:pre-wrap;overflow-wrap:anywhere}.community-moderation button{border:1px solid #d8bcae;border-radius:9px;background:#fff6ef;color:#80513d;padding:10px 16px;cursor:pointer}.community-moderation blockquote{margin:16px 0;background:#faf2eb;padding:14px}</style>